public class CartOrder {
    private final Long customerId;
    private final List<String> items;
    private final String paymentMethod;
    private final String discountCode;
    private final boolean giftWrap;
    private final String deliveryNotes;

    private CartOrder(Builder builder) {
        this.customerId = builder.customerId;
        this.items = builder.items;
        this.paymentMethod = builder.paymentMethod;
        this.discountCode = builder.discountCode;
        this.giftWrap = builder.giftWrap;
        this.deliveryNotes = builder.deliveryNotes;
    }

    public static class Builder {
        private final Long customerId;  // required
        private final List<String> items;  // required
        private String paymentMethod = "CREDIT_CARD";
        private String discountCode;
        private boolean giftWrap = false;
        private String deliveryNotes;

        public Builder(Long customerId, List<String> items) {
            this.customerId = customerId;
            this.items = items;
        }

        public Builder paymentMethod(String method) {
            this.paymentMethod = method;
            return this;  // enables chaining
        }

        public Builder discountCode(String code) {
            this.discountCode = code;
            return this;
        }

        public Builder giftWrap(boolean wrap) {
            this.giftWrap = wrap;
            return this;
        }

        public Builder deliveryNotes(String notes) {
            this.deliveryNotes = notes;
            return this;
        }

        public CartOrder build() {
            if (items.isEmpty()) {
                throw new IllegalStateException("Order must have at least one item");
            }
            return new CartOrder(this);
        }
    }
}

import lombok.Builder;
import lombok.Value;
import java.util.List;

@Value
@Builder
public class CartCheckoutRequest {
    Long customerId;
    List<String> itemIds;
    String paymentMethod;
    String discountCode;
    boolean giftWrap;
    String deliveryNotes;
}

// Usage in Spring controller
@RestController
public class CartController {
    @PostMapping("/checkout")
    public ResponseEntity<String> checkout() {
        var request = CartCheckoutRequest.builder()
            .customerId(12345L)
            .itemIds(List.of("ITEM-001", "ITEM-002"))
            .paymentMethod("CREDIT_CARD")
            .discountCode("SAVE10")
            .giftWrap(true)
            .deliveryNotes("Leave at front door")
            .build();  // Lombok generates this entire Builder

        return ResponseEntity.ok("Order processed");
    }
}

