public class PaymentRequest {
    private final Long userId;  // required
    private final Double amount;  // required
    private final String currency;  // required
    private final String paymentMethod;  // optional
    private final String billingAddress;  // optional
    private final boolean saveCard;  // optional

    private PaymentRequest(Builder builder) {
        this.userId = builder.userId;
        this.amount = builder.amount;
        this.currency = builder.currency;
        this.paymentMethod = builder.paymentMethod;
        this.billingAddress = builder.billingAddress;
        this.saveCard = builder.saveCard;
    }

    public static class Builder {
        // Required fields: final + constructor parameters
        private final Long userId;
        private final Double amount;
        private final String currency;

        // Optional fields: mutable + defaults
        private String paymentMethod = "CREDIT_CARD";
        private String billingAddress;
        private boolean saveCard = false;

        public Builder(Long userId, Double amount, String currency) {
            this.userId = userId;
            this.amount = amount;
            this.currency = currency;
        }

        public Builder paymentMethod(String method) {
            this.paymentMethod = method;
            return this;
        }

        public Builder billingAddress(String address) {
            this.billingAddress = address;
            return this;
        }

        public Builder saveCard(boolean save) {
            this.saveCard = save;
            return this;
        }

        public PaymentRequest build() {
            if (amount <= 0) {
                throw new IllegalStateException("Amount must be positive");
            }
            if (!List.of("USD", "EUR", "GBP").contains(currency)) {
                throw new IllegalStateException("Invalid currency");
            }
            return new PaymentRequest(this);
        }
    }
}

public class ShoppingCart {
    private final Long customerId;
    private final List<CartItem> items;
    private final String promoCode;
    private final boolean expressShipping;

    private ShoppingCart(Builder builder) {
        this.customerId = builder.customerId;
        this.items = List.copyOf(builder.items);
        this.promoCode = builder.promoCode;
        this.expressShipping = builder.expressShipping;
    }

    public static class Builder {
        private final Long customerId;
        private final List<CartItem> items = new ArrayList<>();
        private String promoCode;
        private boolean expressShipping = false;

        public Builder(Long customerId) {
            this.customerId = customerId;
        }

        public Builder addItem(CartItem item) {
            this.items.add(item);
            return this;  // enables chaining
        }

        public Builder promoCode(String code) {
            this.promoCode = code;
            return this;  // return this from every setter
        }

        public Builder expressShipping(boolean express) {
            this.expressShipping = express;
            return this;
        }

        public ShoppingCart build() {
            if (items.isEmpty()) {
                throw new IllegalStateException("Cart must have items");
            }
            return new ShoppingCart(this);
        }
    }
}

// Usage demonstrates chaining readability
var cart = new ShoppingCart.Builder(customerId)
    .addItem(new CartItem("ITEM-001", 2))
    .addItem(new CartItem("ITEM-002", 1))
    .promoCode("SAVE20")
    .expressShipping(true)
    .build();  // fluent, self-documenting construction

