// TELESCOPING CONSTRUCTORS: overloads explode with each optional field
class UserBad {
    UserBad(String id, String email) { this(id, email, null); }
    UserBad(String id, String email, String phone) { this(id, email, phone, null); }
    UserBad(String id, String email, String phone, String bio) { /* ... */ }
    // 4 optionals -> up to 16 overloads; positional args are easy to swap by mistake
}

// BUILDER: one fluent path, named setters, scales linearly
class User {
    private final String id, email, phone, bio;
    private User(Builder b){ id = b.id; email = b.email; phone = b.phone; bio = b.bio; }
    static class Builder {
        private final String id, email;            // required
        private String phone, bio;                 // optional
        Builder(String id, String email){ this.id = id; this.email = email; }
        Builder phone(String p){ this.phone = p; return this; }
        Builder bio(String b){ this.bio = b; return this; }
        User build(){ return new User(this); }
    }
}
// Usage: new User.Builder("u1", "a@b.com").phone("99999").build();
