public class CustomerProfile {
    private final Long userId;
    private final String email;
    private final String phoneNumber;
    private final String shippingAddress;
    private final String billingAddress;
    private final boolean emailNotifications;

    private CustomerProfile(Builder builder) {  // private constructor
        this.userId = builder.userId;
        this.email = builder.email;
        this.phoneNumber = builder.phoneNumber;
        this.shippingAddress = builder.shippingAddress;
        this.billingAddress = builder.billingAddress;
        this.emailNotifications = builder.emailNotifications;
    }

    public static class Builder {
        private final Long userId;  // required field
        private final String email;  // required field
        private String phoneNumber;
        private String shippingAddress;
        private String billingAddress;
        private boolean emailNotifications = true;  // default value

        public Builder(Long userId, String email) {
            this.userId = userId;
            this.email = email;
        }

        public Builder phoneNumber(String phone) {
            this.phoneNumber = phone;
            return this;  // enables chaining
        }

        public Builder shippingAddress(String address) {
            this.shippingAddress = address;
            return this;
        }

        public Builder billingAddress(String address) {
            this.billingAddress = address;
            return this;
        }

        public Builder emailNotifications(boolean enabled) {
            this.emailNotifications = enabled;
            return this;
        }

        public CustomerProfile build() {
            if (email == null || !email.contains("@")) {
                throw new IllegalStateException("Valid email required");
            }
            return new CustomerProfile(this);  // pass Builder to private constructor
        }
    }

    public Long getUserId() { return userId; }
    public String getEmail() { return email; }
}

