public final class ImmutableOrder {  // final class prevents subclassing
    private final Long orderId;
    private final Long customerId;
    private final List<String> items;
    private final String paymentMethod;
    private final String shippingAddress;

    private ImmutableOrder(Builder builder) {
        this.orderId = builder.orderId;
        this.customerId = builder.customerId;
        this.items = List.copyOf(builder.items);  // defensive copy for immutability
        this.paymentMethod = builder.paymentMethod;
        this.shippingAddress = builder.shippingAddress;
    }

    public static class Builder {
        private final Long customerId;  // required, final in Builder
        private Long orderId;
        private List<String> items = List.of();  // immutable default
        private String paymentMethod = "CREDIT_CARD";
        private String shippingAddress;

        public Builder(Long customerId) {
            this.customerId = customerId;
        }

        public Builder orderId(Long id) {
            this.orderId = id;
            return this;
        }

        public Builder items(List<String> items) {
            this.items = items;
            return this;
        }

        public Builder paymentMethod(String method) {
            this.paymentMethod = method;
            return this;
        }

        public Builder shippingAddress(String address) {
            this.shippingAddress = address;
            return this;
        }

        public ImmutableOrder build() {
            if (items.isEmpty()) {
                throw new IllegalStateException("Order must have items");
            }
            return new ImmutableOrder(this);  // single-shot construction
        }
    }

    // Only getters, no setters
    public Long getOrderId() { return orderId; }
    public Long getCustomerId() { return customerId; }
    public List<String> getItems() { return items; }  // already immutable from copyOf
}
